# Let's fetch comments for all tasks in both projects to look for any mention of Bangkok.
import json

access_token = _mem['s6']['access_token']

# Project 280 tasks: 6334-6340
# Project 281 tasks: 6341-6348
# We already have comments for 6340 and 6348, but let's fetch all to be thorough.
all_task_ids = list(range(6334, 6341)) + list(range(6341, 6349))
comments_by_task = {}
for tid in all_task_ids:
    try:
        resp = todoist.show_task_comments(access_token=access_token, task_id=tid)
        comments_by_task[tid] = resp
    except Exception as e:
        comments_by_task[tid] = f"Error: {e}"

# Print comments that mention Bangkok or any location clues
for tid, comments in comments_by_task.items():
    if isinstance(comments, list):
        for c in comments:
            content = c.get('content', '')
            if 'bangkok' in content.lower() or 'thailand' in content.lower() or 'trip' in content.lower():
                print(f"Task {tid}: {content}")
    else:
        print(f"Task {tid}: {comments}")

